/* One session boundary for the new private workspaces. No private browser persistence. */
(() => {'use strict';
 const common={skip:['انتقل إلى المحتوى','Skip to content'],shop:['تسوق','Shop'],cart:['السلة','Cart'],account:['حسابي','Account'],gateTitle:['سجّل الدخول للمتابعة','Sign in to continue'],gateCopy:['افتح حسابك وأكمل بياناتك.','Open your account and complete your profile.'],sellerGate:['أنشئ متجرك من حسابك للبدء.','Create your store from your account to get started.'],loading:['جارٍ تحميل البيانات…','Loading…'],saving:['جارٍ حفظ التغييرات…','Saving changes…'],saved:['تم الحفظ.','Saved.'],error:['تعذّر إكمال العملية. حاول مجددًا.','Could not complete the request. Please retry.'],VERSION_CONFLICT:['تغيّرت البيانات. أعد تحميل المحفوظ قبل التعديل.','The data changed. Reload the saved version before editing.'],TITLE_TAKEN:['اسم المتجر مستخدم. اختر اسمًا آخر.','That store name is taken. Choose another.'],ADDRESS_LIMIT:['يمكن حفظ عشرة عناوين. احذف عنوانًا قبل الإضافة.','You can save ten addresses. Remove one before adding another.'],ADDRESS_INVALID:['تحقق من اسم المستلم والهاتف والعنوان.','Check the recipient, phone and address.'],STORE_PROFILE_INVALID:['تحقق من الحقول وأطوال النصوص.','Check the fields and text lengths.']};
 function create(words,options={}){const $=id=>document.getElementById(id),api=window.BemoAccount;let lang=new URL(location.href).searchParams.get('lang')==='en'?'en':'ar',actor=null,epoch=0,busy=false;
 const t=k=>(words[k]||common[k]||common.error)[lang==='ar'?0:1];
 function language(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('title')+' — BEMO';document.querySelectorAll('[data-t]').forEach(n=>n.textContent=t(n.dataset.t));document.querySelectorAll('[data-route]').forEach(n=>n.href=n.dataset.route+'?lang='+lang);$('cartLink').href='market.html?view=cart&lang='+lang;$('languageButton').textContent=lang==='ar'?'English':'العربية';const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);options.onLanguage?.();}
 function lock(value){busy=value;document.querySelectorAll('#workspace button,#workspace input,#workspace textarea,#newAddress,#refresh').forEach(n=>n.disabled=value);}
 async function run(fn,message='loading'){if(!actor||busy)return;const ticket=epoch,scope=api.merchantScope();lock(true);$('error').hidden=true;$('status').textContent=t(message);const request=async(name,args)=>{const r=await scope.request(name,args);if(ticket!==epoch)throw {code:'SESSION_CHANGED'};if(r.error)throw r.error;return r.data;};try{await fn(request);if(ticket===epoch)$('status').textContent=message==='saving'?t('saved'):'';}catch(e){if(ticket===epoch){$('error').textContent=t(e.code||'error');$('error').hidden=false;$('status').textContent='';}}finally{if(ticket===epoch)lock(false);}}
 const w={$,t,node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;},run,language,lang:()=>lang,busy:()=>busy,ready:()=>Boolean(actor),url:(file,params={})=>file+'?'+new URLSearchParams({lang,...params}),start(){language();$('languageButton').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';language();});api.subscribe(s=>{const id=s.phase==='ready'&&s.profile?.id&&(!options.seller||s.store)?s.profile.id:null;if(id&&id===actor&&s.phase==='ready')return;epoch++;actor=id;busy=false;lock(false);$('status').textContent='';$('error').hidden=true;$('workspace').hidden=!id;$('gate').hidden=Boolean(id);options.onClear?.();if(!id&&options.seller&&s.phase==='ready')$('gate').querySelector('p').textContent=t('sellerGate');if(id)options.onReady?.();});api.initialize();}};return w;
 }
 window.BemoWorkspace={create};
})();
